import{_ as e,I as t,o as l,c as r,b6 as h,j as s,J as i,w as o}from"./chunks/framework.BUXTSoD9.js";const y=JSON.parse('{"title":"Thực hành phát triển nền tảng Agent lập kế hoạch du lịch thông minh","description":"","frontmatter":{},"headers":[],"relativePath":"vi-vn/stage-2/assignments/travel-planning-agent-platform/index.md","filePath":"vi-vn/stage-2/assignments/travel-planning-agent-platform/index.md"}'),d={name:"vi-vn/stage-2/assignments/travel-planning-agent-platform/index.md"},u={style:{margin:"32px 0"}};function g(p,n,k,m,b,v){const a=t("StepBar"),c=t("ClientOnly");return l(),r("div",null,[n[0]||(n[0]=h('<h1 id="thuc-hanh-phat-trien-nen-tang-agent-lap-ke-hoach-du-lich-thong-minh" tabindex="-1">Thực hành phát triển nền tảng Agent lập kế hoạch du lịch thông minh <a class="header-anchor" href="#thuc-hanh-phat-trien-nen-tang-agent-lap-ke-hoach-du-lich-thong-minh" aria-label="Permalink to “Thực hành phát triển nền tảng Agent lập kế hoạch du lịch thông minh”">​</a></h1><h2 id="tong-quan" tabindex="-1">Tổng quan <a class="header-anchor" href="#tong-quan" aria-label="Permalink to “Tổng quan”">​</a></h2><p>Dự án thực chiến này yêu cầu bạn hoàn thành một nền tảng Agent lập kế hoạch du lịch thông minh dựa trên một PRD thực tế, xây dựng từ đầu. Bạn sẽ xây dựng một sản phẩm AI hoàn chỉnh có thể nhận đầu vào có cấu trúc, tạo lịch trình hàng ngày, hỗ trợ lưu trữ và tái sử dụng — không chỉ là chatbot, mà là một sản phẩm có khả năng quản lý tác vụ.</p><p>Đây là phần thực hành tổng hợp của Stage 2. Thách thức cốt lõi của dự án này là: làm thế nào để AI tạo ra kế hoạch lịch trình có cấu trúc và sử dụng được, chứ không phải một đoạn văn bản dài không thể thao tác.</p><h2 id="kien-thuc-tien-quyet" tabindex="-1">Kiến thức tiên quyết <a class="header-anchor" href="#kien-thuc-tien-quyet" aria-label="Permalink to “Kiến thức tiên quyết”">​</a></h2><p>Trước khi bắt đầu dự án này, bạn nên đã nắm được các nội dung sau:</p><ul><li>Thiết kế trang frontend và sử dụng thư viện component (<a href="./../../frontend/ui-design/">Thiết kế UI</a>, <a href="./../../frontend/modern-component-library/">Thư viện component hiện đại</a>)</li><li>Thiết kế và phát triển API backend (<a href="./../../backend/ai-interface-code/">Viết code API</a>)</li><li>Cơ sở dữ liệu cơ bản và Supabase (<a href="./../../backend/database-supabase/">Từ cơ sở dữ liệu đến Supabase</a>)</li><li>Quy trình làm việc Git và triển khai (<a href="./../../backend/git-workflow/">Git và GitHub</a>, <a href="./../../backend/zeabur-deployment/">Triển khai ứng dụng Web</a>)</li></ul><h2 id="muc-tieu-hoc-tap" tabindex="-1">Mục tiêu học tập <a class="header-anchor" href="#muc-tieu-hoc-tap" aria-label="Permalink to “Mục tiêu học tập”">​</a></h2><p>Sau khi hoàn thành bài thực hành này, bạn sẽ có thể:</p><ol><li>Đọc PRD và từ đó trích xuất danh sách công việc phát triển nền tảng Agent</li><li>Thiết kế biểu mẫu đầu vào có cấu trúc và định dạng đầu ra có cấu trúc</li><li>Triển khai lớp điều phối Agent, xử lý đầu vào người dùng, gọi mô hình và lưu trữ kết quả</li><li>Xây dựng chuỗi nghiệp vụ &quot;tạo → lưu → tái sử dụng&quot;</li><li>Hoàn thành liên hợp đầu cuối, bàn giao nguyên mẫu sản phẩm AI có thể demo</li></ol><h2 id="gioi-thieu-du-an" tabindex="-1">Giới thiệu dự án <a class="header-anchor" href="#gioi-thieu-du-an" aria-label="Permalink to “Giới thiệu dự án”">​</a></h2><p>Sản phẩm bạn cần xây dựng là một nền tảng Agent lập kế hoạch du lịch thông minh:</p><table tabindex="0"><thead><tr><th>Chức năng</th><th>Mô tả</th></tr></thead><tbody><tr><td><strong>Lập kế hoạch lịch trình</strong></td><td>Người dùng nhập điểm xuất phát, điểm đến, ngày, ngân sách và sở thích, hệ thống tạo lịch trình hàng ngày</td></tr><tr><td><strong>Phân bổ ngân sách</strong></td><td>Kết quả lịch trình bao gồm phân bổ ngân sách và đề xuất</td></tr><tr><td><strong>Quản lý lịch sử</strong></td><td>Người dùng có thể lưu kế hoạch lịch sử, tạo lại, xuất</td></tr><tr><td><strong>Back-office quản trị</strong></td><td>Quản trị viên xem điểm đến phổ biến, tác vụ thất bại và phản hồi người dùng</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Đường dẫn PRD</p><p>Tài liệu yêu cầu của dự án này nằm trên GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/travel-planning-agent-platform/PRD.md" target="_blank" rel="noreferrer">Xem PRD</a></p></div>',14)),s("div",u,[i(c,null,{default:o(()=>[i(a,{active:0,items:[{title:"Phân tích yêu cầu",description:"Đọc PRD, xác định trang, điều phối Agent, cấu trúc đầu vào/đầu ra"},{title:"Xây dựng khung",description:"Dùng AI tạo khung trang chủ, trang lập kế hoạch, trang lịch sử, trang back-office"},{title:"Phát triển lặp",description:"Bổ sung từng module: đầu ra có cấu trúc, trạng thái tác vụ, quản lý lịch sử"},{title:"Liên hợp & triển khai",description:"Chạy đầu cuối, triển khai và chuẩn bị demo"}]})]),_:1})]),n[1]||(n[1]=h(`<h2 id="phan-1-phan-tich-yeu-cau" tabindex="-1">Phần 1: Phân tích yêu cầu <a class="header-anchor" href="#phan-1-phan-tich-yeu-cau" aria-label="Permalink to “Phần 1: Phân tích yêu cầu”">​</a></h2><h3 id="_1-1-đoc-prd" tabindex="-1">1.1 Đọc PRD <a class="header-anchor" href="#_1-1-đoc-prd" aria-label="Permalink to “1.1 Đọc PRD”">​</a></h3><p>Mở tài liệu PRD, tập trung trả lời các câu hỏi sau:</p><ul><li>Phiên bản đầu tiên có chỉ làm một điểm đến không?</li><li>Đầu ra lịch trình có bắt buộc phải có cấu trúc không? Cấu trúc là gì?</li><li>Khả năng xuất sâu đến đâu? (Liên kết chia sẻ / PDF / Hình ảnh)</li><li>Phạm vi thống kê back-office và nhật ký tác vụ là gì?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Nếu các câu hỏi trên chưa có câu trả lời rõ ràng, đừng bắt đầu viết code. Hiểu sai yêu cầu là nguyên nhân phổ biến nhất dẫn đến phải làm lại.</p></div><h3 id="_1-2-xac-nhan-kien-truc-he-thong" tabindex="-1">1.2 Xác nhận kiến trúc hệ thống <a class="header-anchor" href="#_1-2-xac-nhan-kien-truc-he-thong" aria-label="Permalink to “1.2 Xác nhận kiến trúc hệ thống”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; planner[&quot;Trang lập kế hoạch&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  planner --&gt; agent[&quot;Lớp điều phối Agent&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agent --&gt; model[&quot;Gọi mô hình&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agent --&gt; db[&quot;Cơ sở dữ liệu&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  db --&gt; history[&quot;Kế hoạch lịch sử&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  db --&gt; admin[&quot;Thống kê &amp; nhật ký back-office&quot;]</span></span></code></pre></div><h2 id="phan-2-xay-dung-khung-du-an" tabindex="-1">Phần 2: Xây dựng khung dự án <a class="header-anchor" href="#phan-2-xay-dung-khung-du-an" aria-label="Permalink to “Phần 2: Xây dựng khung dự án”">​</a></h2><h3 id="_2-1-tao-trang-frontend" tabindex="-1">2.1 Tạo trang frontend <a class="header-anchor" href="#_2-1-tao-trang-frontend" aria-label="Permalink to “2.1 Tạo trang frontend”">​</a></h3><p>Tham khảo prompt:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Vui lòng dựa trên PRD hiện tại, giúp tôi tạo khung frontend của nền tảng Agent lập kế hoạch du lịch thông minh.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Yêu cầu:</span></span>
<span class="line"><span>1. Trang bao gồm: trang chủ, trang lập kế hoạch, trang chi tiết lịch trình, trang lịch sử, trang quản lý</span></span>
<span class="line"><span>2. Trang lập kế hoạch bên trái là biểu mẫu, bên phải là xem trước kết quả</span></span>
<span class="line"><span>3. Trước tiên chỉ tạo cấu trúc trang và dữ liệu giả, không kết nối API thực tế</span></span>
<span class="line"><span>4. Phong cách phải giống sản phẩm AI hiện đại</span></span></code></pre></div><h3 id="_2-2-xac-minh-cau-truc-trang" tabindex="-1">2.2 Xác minh cấu trúc trang <a class="header-anchor" href="#_2-2-xac-minh-cau-truc-trang" aria-label="Permalink to “2.2 Xác minh cấu trúc trang”">​</a></h3><p>Kiểm tra từng mục:</p><ul><li>[ ] Trường biểu mẫu trang lập kế hoạch có khớp với PRD không</li><li>[ ] Khu vực xem trước kết quả có thể hiển thị dữ liệu lịch trình có cấu trúc</li><li>[ ] Trang lịch sử có thể hiển thị nhiều kế hoạch</li><li>[ ] Trang back-office quản trị có thể hiển thị dữ liệu thống kê</li></ul><h2 id="phan-3-phat-trien-lap" tabindex="-1">Phần 3: Phát triển lặp <a class="header-anchor" href="#phan-3-phat-trien-lap" aria-label="Permalink to “Phần 3: Phát triển lặp”">​</a></h2><h3 id="_3-1-trien-khai-theo-module" tabindex="-1">3.1 Triển khai theo module <a class="header-anchor" href="#_3-1-trien-khai-theo-module" aria-label="Permalink to “3.1 Triển khai theo module”">​</a></h3><ol><li><strong>Xác thực</strong>: Đăng ký, đăng nhập</li><li><strong>Biểu mẫu lập kế hoạch</strong>: Đầu vào có cấu trúc (điểm xuất phát, điểm đến, ngày, ngân sách, sở thích)</li><li><strong>Điều phối Agent</strong>: Nhận đầu vào → Gọi mô hình → Phân tích đầu ra có cấu trúc</li><li><strong>Hiển thị kết quả</strong>: Lịch trình hiển thị theo ngày, phân bổ ngân sách, đề xuất</li><li><strong>Quản lý lịch sử</strong>: Lưu kế hoạch, tạo lại, xuất</li><li><strong>Back-office quản trị</strong>: Điểm đến phổ biến, tác vụ thất bại, phản hồi người dùng</li><li><strong>Trạng thái tác vụ</strong>: Quản lý trạng thái đang tạo / thành công / thất bại và ghi lỗi</li></ol><h3 id="_3-2-tu-kiem-tra-module" tabindex="-1">3.2 Tự kiểm tra module <a class="header-anchor" href="#_3-2-tu-kiem-tra-module" aria-label="Permalink to “3.2 Tự kiểm tra module”">​</a></h3><table tabindex="0"><thead><tr><th>Mục kiểm tra</th><th>Phương pháp xác minh</th></tr></thead><tbody><tr><td>Tính đầy đủ đầu vào</td><td>Trường biểu mẫu có khớp với PRD không</td></tr><tr><td>Tính cấu trúc đầu ra</td><td>Kết quả lịch trình có phải là dữ liệu có cấu trúc (chứ không phải một đoạn văn bản dài) không</td></tr><tr><td>Tính nhất quán dữ liệu</td><td>Dữ liệu trip, itinerary, logs có khớp nhau không</td></tr><tr><td>Xác minh chuỗi hoàn chỉnh</td><td>Có thể demo &quot;nhập → tạo → lưu → tạo lại&quot; không</td></tr></tbody></table><h2 id="phan-4-lien-hop-va-trien-khai" tabindex="-1">Phần 4: Liên hợp và Triển khai <a class="header-anchor" href="#phan-4-lien-hop-va-trien-khai" aria-label="Permalink to “Phần 4: Liên hợp và Triển khai”">​</a></h2><h3 id="_4-1-kiem-thu-đau-cuoi" tabindex="-1">4.1 Kiểm thử đầu cuối <a class="header-anchor" href="#_4-1-kiem-thu-đau-cuoi" aria-label="Permalink to “4.1 Kiểm thử đầu cuối”">​</a></h3><p>Ít nhất xác minh các kịch bản sau:</p><ul><li>Nhập tham số lịch trình → Tạo lịch trình hàng ngày → Xem phân bổ ngân sách → Lưu vào lịch sử</li><li>Tạo lại lịch trình từ bản ghi lịch sử</li><li>Quản trị viên xem thống kê tác vụ và nhật ký thất bại</li></ul><h2 id="san-pham-ban-giao" tabindex="-1">Sản phẩm bàn giao <a class="header-anchor" href="#san-pham-ban-giao" aria-label="Permalink to “Sản phẩm bàn giao”">​</a></h2><p>Sau khi hoàn thành dự án này, bạn cần nộp các nội dung sau:</p><ul><li>[ ] Liên kết demo trực tuyến có thể truy cập</li><li>[ ] Liên kết kho mã nguồn (bao gồm README)</li><li>[ ] Tài liệu PRD</li><li>[ ] Ảnh chụp màn hình các trang cốt lõi (trang lập kế hoạch, trang chi tiết lịch trình, trang lịch sử, back-office quản trị)</li><li>[ ] Video demo 60 giây</li></ul><h2 id="tieu-chi-cham-điem" tabindex="-1">Tiêu chí chấm điểm <a class="header-anchor" href="#tieu-chi-cham-điem" aria-label="Permalink to “Tiêu chí chấm điểm”">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Yêu cầu cơ bản</th><th>Yêu cầu nâng cao</th></tr></thead><tbody><tr><td>Căn chỉnh PRD</td><td>Trang, chức năng, cấu trúc dữ liệu cơ bản khớp với PRD</td><td>Có thể giải thích rõ ràng quyết định thiết kế</td></tr><tr><td>Chuỗi sản phẩm</td><td>Lập kế hoạch → Lưu → Lịch sử → Tạo lại có thể chạy qua</td><td>Hỗ trợ xuất và chia sẻ</td></tr><tr><td>Chất lượng đầu ra</td><td>Kết quả lịch trình có cấu trúc và dễ đọc</td><td>Phân bổ ngân sách hợp lý, đề xuất có tính định hướng</td></tr><tr><td>Khả năng back-office</td><td>Thống kê tác vụ và nhật ký thất bại có thể xem</td><td>Có phân tích điểm đến phổ biến</td></tr><tr><td>Độ hoàn thiện kỹ thuật</td><td>Frontend, backend, cơ sở dữ liệu, chuỗi gọi mô hình đã kết nối</td><td>Quản lý trạng thái tác vụ hoàn thiện, lỗi có thể truy vết</td></tr></tbody></table><h2 id="tai-lieu-tham-khao" tabindex="-1">Tài liệu tham khảo <a class="header-anchor" href="#tai-lieu-tham-khao" aria-label="Permalink to “Tài liệu tham khảo”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">Thiết kế UI</a></li><li><a href="./../../frontend/modern-component-library/">Sử dụng thư viện component hiện đại để cập nhật giao diện</a></li><li><a href="./../../backend/database-supabase/">Từ cơ sở dữ liệu đến Supabase</a></li><li><a href="./../../backend/ai-interface-code/">Mô hình hỗ trợ viết code API và tài liệu API bằng mô hình lớn</a></li><li><a href="./../../backend/git-workflow/">Quy trình làm việc Git và GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">Cách triển khai ứng dụng Web</a></li></ul>`,30))])}const P=e(d,[["render",g]]);export{y as __pageData,P as default};
